class LinearChaCha20:
    def __init__(self):
        self._state = []
        self._initial_state = [] 

    def _quarter_round(self, x, a, b, c, d):
        x[a] = operator.xor(x[a], x[b]); x[d] = operator.xor(x[d], x[a]); x[d] = rotate(x[d], _sage_const_16 )
        x[c] = operator.xor(x[c], x[d]); x[b] = operator.xor(x[b], x[c]); x[b] = rotate(x[b], _sage_const_12 )
        x[a] = operator.xor(x[a], x[b]); x[d] = operator.xor(x[d], x[a]); x[d] = rotate(x[d], _sage_const_8 )
        x[c] = operator.xor(x[c], x[d]); x[b] = operator.xor(x[b], x[c]); x[b] = rotate(x[b], _sage_const_7 )

    def _inner_block(self, state):
        self._quarter_round(state, _sage_const_0 , _sage_const_4 , _sage_const_8 , _sage_const_12 ); self._quarter_round(state, _sage_const_1 , _sage_const_5 , _sage_const_9 , _sage_const_13 )
