    def encrypt(self, m, key, iv):
        c = b''
        self._counter = _sage_const_1 
        for i in range(_sage_const_0 , len(m), _sage_const_64 ):
            self._setup_state(key, iv)
            for j in range(_sage_const_10 ):
                self._inner_block(self._state)
            for k in range(_sage_const_16 ):
                self._state[k] = (self._state[k] + self._initial_state[k]) % (_sage_const_2  ** _sage_const_32 )
            c += xor_bytes(m[i:i+_sage_const_64 ], words_to_bytes(self._state))
            self._counter += _sage_const_1 
        return c

    def decrypt(self, c, key, iv):
        return self.encrypt(c, key, iv)

        





